mapper.select:
SELECT COUNT(DISTINCT visitor_id)
FROM pisces_experiment_exposure
WHERE experiment_id = #{experimentId}
  AND group_id = #{groupId}

SELECT COUNT(1)
FROM pisces_experiment_exposure
WHERE experiment_id = #{experimentId}
  AND group_id = #{groupId}

  AND exposed_at >= #{startTime}


  AND exposed_at <= #{endTime}

SELECT id, exposure_id, experiment_id, visitor_id, group_id, scene, properties_json, idempotency_key,
       exposed_at, created_at
FROM pisces_experiment_exposure
WHERE experiment_id = #{experimentId}
  AND group_id = #{groupId}

  AND exposed_at >= #{startTime}


  AND exposed_at <= #{endTime}

ORDER BY exposed_at ASC, id ASC

SELECT id, exposure_id, experiment_id, visitor_id, group_id, scene, properties_json, idempotency_key,
       exposed_at, created_at
FROM pisces_experiment_exposure
WHERE experiment_id = #{experimentId}
  AND group_id = #{groupId}

  AND exposed_at >= #{startTime}


  AND exposed_at <= #{endTime}

ORDER BY exposed_at ASC, id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT x.id, x.exposure_id, x.experiment_id, x.visitor_id, x.group_id, x.scene, x.properties_json,
       x.idempotency_key, x.exposed_at, x.created_at
FROM pisces_experiment_exposure x
LEFT JOIN pisces_event_materialization m
  ON m.fact_kind = 'EXPOSURE'
 AND m.fact_id = x.exposure_id
WHERE x.experiment_id = #{experimentId}
  AND x.group_id = #{groupId}
  AND m.fact_id IS NULL

  AND x.exposed_at >= #{startTime}


  AND x.exposed_at <= #{endTime}

ORDER BY x.exposed_at ASC, x.id ASC

SELECT x.id, x.exposure_id, x.experiment_id, x.visitor_id, x.group_id, x.scene, x.properties_json,
       x.idempotency_key, x.exposed_at, x.created_at
FROM pisces_experiment_exposure x
LEFT JOIN pisces_event_materialization m
  ON m.fact_kind = 'EXPOSURE'
 AND m.fact_id = x.exposure_id
WHERE x.experiment_id = #{experimentId}
  AND x.group_id = #{groupId}
  AND m.fact_id IS NULL

  AND x.exposed_at >= #{startTime}


  AND x.exposed_at <= #{endTime}

ORDER BY x.exposed_at ASC, x.id ASC
LIMIT #{limit} OFFSET #{offset}

